import{_ as n,o as r,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Recherche: Die Kontinuität der Gewalt – Der Fall Peršmanhof (ERWEITERT)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/persmanhof-kontinuitaet.md","filePath":"recherche/persmanhof-kontinuitaet.md"}'),a={name:"recherche/persmanhof-kontinuitaet.md"};function s(o,e,l,d,h,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="recherche-die-kontinuitat-der-gewalt-–-der-fall-persmanhof-erweitert" tabindex="-1">Recherche: Die Kontinuität der Gewalt – Der Fall Peršmanhof (ERWEITERT) <a class="header-anchor" href="#recherche-die-kontinuitat-der-gewalt-–-der-fall-persmanhof-erweitert" aria-label="Permalink to &quot;Recherche: Die Kontinuität der Gewalt – Der Fall Peršmanhof (ERWEITERT)&quot;">​</a></h1><h2 id="_1-das-historische-fundament-das-massaker-von-1945" tabindex="-1">1. Das historische Fundament: Das Massaker von 1945 <a class="header-anchor" href="#_1-das-historische-fundament-das-massaker-von-1945" aria-label="Permalink to &quot;1. Das historische Fundament: Das Massaker von 1945&quot;">​</a></h2><ul><li><strong>Datum:</strong> 25. April 1945.</li><li><strong>Täter:</strong> SS-Polizeiregiment 13.</li><li><strong>Opfer:</strong> 11 Mitglieder der Familien Sadovnik und Kogoj (darunter 7 Kinder).</li><li><strong>Kontext:</strong> Vernichtung des slowenischen Widerstands kurz vor Kriegsende. Der Peršmanhof ist heute das einzige Museum, das den bewaffneten Widerstand gegen das NS-Regime in Österreich umfassend dokumentiert.</li></ul><h2 id="_2-der-skandalose-polizeieinsatz-27-juli-2025" tabindex="-1">2. Der skandalöse Polizeieinsatz (27. Juli 2025) <a class="header-anchor" href="#_2-der-skandalose-polizeieinsatz-27-juli-2025" aria-label="Permalink to &quot;2. Der skandalöse Polizeieinsatz (27. Juli 2025)&quot;">​</a></h2><ul><li><strong>Akteure:</strong> Über 30 Beamte, Schnelle Interventionsgruppe (SIG), Diensthunde, Hubschrauber, Drohnen.</li><li><strong>Anordnung:</strong> Eigenmächtig durch den stellv. Leiter des LSE Kärnten (Staatsschutz) ohne schriftlichen Befehl.</li><li><strong>Vorwand:</strong> Übertretungen des Kärntner Naturschutz- und Campingplatzgesetzes.</li><li><strong>Skandal-Begründung des LSE:</strong> Das Camp stelle einen „sittenwidrigen Umgang mit der Gedenkstätte“ dar. Dies wurde von den Nachfahren der Opfer (z.B. Bernard Sadovnik) als Gipfel der Pietätlosigkeit und historische Anmaßung empfunden.</li><li><strong>Eingriffe:</strong> Rechtswidriges Eindringen in das Museum („Hausdurchsuchung“ ohne Befehl), Identitätsfeststellungen unter dem Vorwand der „groben Anstandsverletzung“.</li></ul><h2 id="_3-die-parlamentarische-aufarbeitung-september-oktober-2025" tabindex="-1">3. Die parlamentarische Aufarbeitung (September/Oktober 2025) <a class="header-anchor" href="#_3-die-parlamentarische-aufarbeitung-september-oktober-2025" aria-label="Permalink to &quot;3. Die parlamentarische Aufarbeitung (September/Oktober 2025)&quot;">​</a></h2><ul><li><strong>Anfrage der Grünen:</strong> Olga Voglauer und Lukas Hammer deckten die Unverhältnismäßigkeit auf.</li><li><strong>Reaktion Karner (ÖVP):</strong> Einsetzung einer Expertenkommission, aber zunächst Ausweichen bei kritischen Fragen zur BH Völkermarkt.</li><li><strong>FPÖ-Position:</strong> Gernot Darmann bezeichnete das Camp als „Treffpunkt der linksextremen Antifa“ und rechtfertigte den Einsatz vollumfänglich – eine Täter-Opfer-Umkehr, die den Gedenkort entwertet.</li></ul><h2 id="_4-die-pressekonferenz-der-betroffenen-24-oktober-2025" tabindex="-1">4. Die Pressekonferenz der Betroffenen (24. Oktober 2025) <a class="header-anchor" href="#_4-die-pressekonferenz-der-betroffenen-24-oktober-2025" aria-label="Permalink to &quot;4. Die Pressekonferenz der Betroffenen (24. Oktober 2025)&quot;">​</a></h2><p>Zentrale Stimmen des Unmuts im Presseclub Concordia:</p><ul><li><strong>Nikolaj Orasche (Partisanenverband):</strong> Sprach von „strukturellem Antislowenismus“ in Kärntner Institutionen. Der Einsatz sei ein Angriff auf die Identität der Volksgruppe.</li><li><strong>Ertuğrul Bayraktar (Aktivist):</strong> Kritisierte scharf das Ausbleiben einer Entschuldigung durch Innenminister Karner: „Eine einfache Entschuldigung wäre ein Anfang gewesen.“</li><li><strong>Rudolf Vouk (Anwalt):</strong> Bestätigte den Missbrauch des Verwaltungsrechts zur polizeilichen Datensammlung durch den Staatsschutz.</li><li><strong>Das Angebot:</strong> Die Museumsbetreiber luden die Verantwortlichen zur Versöhnung für 2026 ein – unter der Bedingung einer ehrlichen Aufarbeitung.</li></ul><h2 id="_5-das-finale-gerichtsurteil-16-april-2026" tabindex="-1">5. Das finale Gerichtsurteil (16. April 2026) <a class="header-anchor" href="#_5-das-finale-gerichtsurteil-16-april-2026" aria-label="Permalink to &quot;5. Das finale Gerichtsurteil (16. April 2026)&quot;">​</a></h2><ul><li><strong>Landesverwaltungsgericht Kärnten:</strong> Bestätigt die vollständige Rechtswidrigkeit der Identitätsfeststellungen.</li><li><strong>Fazit:</strong> Der Staatsschutz hat seine Befugnisse missbraucht, um einen antifaschistischen Gedenkort zu kriminalisieren.</li></ul><h2 id="_6-die-hydra-connection-film-integration" tabindex="-1">6. Die Hydra-Connection (Film-Integration) <a class="header-anchor" href="#_6-die-hydra-connection-film-integration" aria-label="Permalink to &quot;6. Die Hydra-Connection (Film-Integration)&quot;">​</a></h2><ul><li><strong>Motiv:</strong> Die „Zangenbewegung“ zwischen bürokratischer Willkür (Campinggesetz) und historischer Amnesie.</li><li><strong>Kontrast:</strong> Während Wöginger-Interventionen als „Bürgernähe“ verharmlost werden, wird echtes Bürgerengagement am Peršmanhof mit Hubschraubern bekämpft.</li><li><strong>Symbolik:</strong> Die Taschenlampe des Polizisten leuchtet auf die Fotos der ermordeten Kinder – die Hydra blickt in den Spiegel ihrer eigenen Geschichte und erkennt sich nicht.</li></ul>',14)])])}const m=n(a,[["render",s]]);export{c as __pageData,m as default};
